#define ANIM_FPS_DELAY 50  // 每帧延时 ms
#define FRAMES35_COUNT 35
#define SSH1106_I2C_ADDR 0x3C  //或者0x3D，1.3寸OLED显示屏采用SSH1106芯片驱动
//默认硬件I2C引脚为P13和P15

#ifndef EXAMPLE_I2C_SCL_PIN
#define EXAMPLE_I2C_SCL_PIN TUYA_GPIO_NUM_13
#endif

#ifndef EXAMPLE_I2C_SDA_PIN
#define EXAMPLE_I2C_SDA_PIN TUYA_GPIO_NUM_15
#endif


void ssh1106_write(uint8_t ctrl, const uint8_t *data, uint16_t len)
{
    uint8_t hdr = ctrl;          // 保持 0x00/0x40
    tkl_i2c_master_send(TUYA_I2C_NUM_0, SSH1106_I2C_ADDR, &hdr, 1, 2);
    tkl_i2c_master_send(TUYA_I2C_NUM_0, SSH1106_I2C_ADDR, data, len, 2);
}

//初始化序列
static const uint8_t init_seq[] = {
    0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00,
    0x40, 0x8D, 0x14, 0x20, 0x00, 0xA1, 0xC8,
    0xDA, 0x12, 0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6, 0xAF
};

void ssh1106_refresh(const uint8_t *buf128x64)
{
    ssh1106_write(0x00, (uint8_t[]){0x21,0,127,0x22,0,7}, 6); // 设置列/页地址
    ssh1106_write(0x40, (uint8_t*)buf128x64, 1024);           // 1 KB 数据
    TAL_PR_NOTICE("ssh1106_refresh() called");
}

static uint8_t disp_buf[128*64/8];

void my_flush_cb(lv_disp_drv_t *drv, const lv_area_t *area, lv_color_t *color_p)
{
    /* color_p 在 LV_COLOR_DEPTH=1 时就是 128×64 位图 */
    memcpy(disp_buf, color_p, 1024);
    ssh1106_refresh(disp_buf);
    lv_disp_flush_ready(drv);
    
}

//i2c_cfg配置
static const TUYA_IIC_BASE_CFG_T i2c_cfg = {
    .role      = TUYA_IIC_MODE_MASTER,      ///< IIC Master
    .speed     = TUYA_IIC_BUS_SPEED_400K,   // 400 kHz
    .addr_width = TUYA_IIC_ADDRESS_7BIT     ///< 7-bit address mode, or called 8-bit address mode
};

void emoji_oled_init(void)
{
    tkl_i2c_init(TUYA_I2C_NUM_0, &i2c_cfg);
    ssh1106_write(0x00, init_seq, sizeof(init_seq));   // 发送初始化序列
}

// 假设 frames35 定义在别的文件，这里声明
//extern const uint8_t frames35[][1024];

void emoji_play_frames35(uint8_t play_times)
{
    uint8_t page;
    for (page = 0; page < 8; page++) {
    ssh1106_write(0x00, (uint8_t[]){0xB0 | page, 0x00, 0x10}, 3); // 设置页和列低/高地址
    uint8_t ones[128];
    memset(ones, 0xFF, 128);
    ssh1106_write(0x40, ones, 128);          // 整页全亮
}
}




